import{_ as o,W as d,s as l,u as n,ah as c,I as i,w as s,Z as t,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"使用 fdisk 和 fallocate 命令创建交换分区 | LCTT x X-CMD","titleTemplate":false,"description":"使用 fdisk 和 fallocate 命令创建交换分区 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 fdisk 和 fallocate 命令创建交换分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 fdisk 和 fallocate 命令创建交换分区 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands","title":"使用 fdisk 和 fallocate 命令创建交换分区","tag":"201801"},"relativePath":"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands.md","filePath":"[post].md"}'),r={name:"201801/20170802 Creating SWAP partition using FDISK - FALLOCATE commands.md"};function u(h,a,g,f,b,m){const e=d("Link");return n(),l("div",null,[a[13]||(a[13]=c(`<h1 id="使用-fdisk-和-fallocate-命令创建交换分区" tabindex="-1">使用 fdisk 和 fallocate 命令创建交换分区 <a class="header-anchor" href="#使用-fdisk-和-fallocate-命令创建交换分区" aria-label="Permalink to 使用 fdisk 和 fallocate 命令创建交换分区">​</a></h1><p>交换分区在物理内存（RAM）被填满时用来保持内存中的内容。当 RAM 被耗尽，Linux 会将内存中不活动的页移动到交换空间中，从而空出内存给系统使用。虽然如此，但交换空间不应被认为是物理内存的替代品。</p><p>大多数情况下，建议交换内存的大小为物理内存的 1 到 2 倍。也就是说如果你有 8GB 内存, 那么交换空间大小应该介于8-16 GB。</p><p>若系统中没有配置交换分区，当内存耗尽后，系统可能会杀掉正在运行中的进程/应用，从而导致系统崩溃。在本文中，我们将学会如何为 Linux 系统添加交换分区，我们有两个办法：</p><ul><li>使用 fdisk 命令</li><li>使用 fallocate 命令</li></ul><h3 id="第一个方法-使用-fdisk-命令" tabindex="-1">第一个方法（使用 fdisk 命令） <a class="header-anchor" href="#第一个方法-使用-fdisk-命令" aria-label="Permalink to 第一个方法（使用 fdisk 命令）">​</a></h3><p>通常，系统的第一块硬盘会被命名为 <code>/dev/sda</code>，而其中的分区会命名为 <code>/dev/sda1</code> 、 <code>/dev/sda2</code>。 本文我们使用的是一块有两个主分区的硬盘，两个分区分别为 <code>/dev/sda1</code>、 <code>/dev/sda2</code>，而我们使用 <code>/dev/sda3</code> 来做交换分区。</p><p>首先创建一个新分区，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ fdisk /dev/sda</span></span></code></pre></div><p>按 <code>n</code> 来创建新分区。系统会询问你从哪个柱面开始，直接按回车键使用默认值即可。然后系统询问你到哪个柱面结束, 这里我们输入交换分区的大小（比如 1000MB）。这里我们输入 <code>+1000M</code>。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/fidsk.jpg?resize=668%2C211" alt="swap"></p><p>现在我们创建了一个大小为 1000MB 的磁盘了。但是我们并没有设置该分区的类型，我们按下 <code>t</code> 然后回车，来设置分区类型。</p><p>现在我们要输入分区编号，这里我们输入 <code>3</code>，然后输入磁盘分类号，交换分区的分区类型为 <code>82</code> （要显示所有可用的分区类型，按下 <code>l</code> ) ，然后再按下 <code>w</code> 保存磁盘分区表。</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2017/02/fidsk-swap-select.jpg?resize=620%2C157" alt="swap"></p><p>再下一步使用 <code>mkswap</code> 命令来格式化交换分区：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkswap /dev/sda3</span></span></code></pre></div><p>然后激活新建的交换分区：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ swapon /dev/sda3</span></span></code></pre></div><p>然而我们的交换分区在重启后并不会自动挂载。要做到永久挂载，我们需要添加内容到 <code>/etc/fstab</code> 文件中。打开 <code>/etc/fstab</code> 文件并输入下面行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda3 swap  swap  default  0  0</span></span></code></pre></div><p>保存并关闭文件。现在每次重启后都能使用我们的交换分区了。</p><h3 id="第二种方法-使用-fallocate-命令" tabindex="-1">第二种方法（使用 fallocate 命令） <a class="header-anchor" href="#第二种方法-使用-fallocate-命令" aria-label="Permalink to 第二种方法（使用 fallocate 命令）">​</a></h3><p>我推荐用这种方法因为这个是最简单、最快速的创建交换空间的方法了。<code>fallocate</code> 是最被低估和使用最少的命令之一了。 <code>fallocate</code> 命令用于为文件预分配块/大小。</p><p>使用 <code>fallocate</code> 创建交换空间，我们首先在 <code>/</code> 目录下创建一个名为 <code>swap_space</code> 的文件。然后分配 2GB 到 <code>swap_space</code> 文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ fallocate -l 2G /swap_space</span></span></code></pre></div><p>我们运行下面命令来验证文件大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls -lh /swap_space</span></span></code></pre></div><p>然后更改文件权限，让 <code>/swap_space</code> 更安全：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ chmod 600 /swap_space</span></span></code></pre></div><p>这样只有 root 可以读写该文件了。我们再来格式化交换分区（LCTT 译注：虽然这个 <code>swap_space</code> 是个文件，但是我们把它当成是分区来挂载）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkswap /swap_space</span></span></code></pre></div><p>然后启用交换空间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ swapon -s</span></span></code></pre></div><p>每次重启后都要重新挂载磁盘分区。因此为了使之持久化，就像上面一样，我们编辑 <code>/etc/fstab</code> 并输入下面行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/swap_space swap  swap  sw  0  0</span></span></code></pre></div><p>保存并退出文件。现在我们的交换分区会一直被挂载了。我们重启后可以在终端运行 <code>free -m</code> 来检查交换分区是否生效。</p><p>我们的教程至此就结束了，希望本文足够容易理解和学习，如果有任何疑问欢迎提出。</p><hr>`,38)),i("p",null,[a[1]||(a[1]=s("via: ")),t(e,{href:"http://linuxtechlab.com/create-swap-using-fdisk-fallocate/"},{default:p(()=>a[0]||(a[0]=[s("http://linuxtechlab.com/create-swap-using-fdisk-fallocate/")])),_:1})]),i("p",null,[a[5]||(a[5]=s("作者：")),t(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:p(()=>a[2]||(a[2]=[s("Shusain")])),_:1}),a[6]||(a[6]=s(" 译者：")),t(e,{href:"https://github.com/lujun9972"},{default:p(()=>a[3]||(a[3]=[s("lujun9972")])),_:1}),a[7]||(a[7]=s(" 校对：")),t(e,{href:"https://github.com/wxy"},{default:p(()=>a[4]||(a[4]=[s("wxy")])),_:1})]),i("p",null,[a[10]||(a[10]=s("本文由 ")),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>a[8]||(a[8]=[s("LCTT")])),_:1}),a[11]||(a[11]=s(" 原创编译，")),t(e,{href:"https://linux.cn/"},{default:p(()=>a[9]||(a[9]=[s("Linux中国")])),_:1}),a[12]||(a[12]=s(" 荣誉推出"))])])}const w=o(r,[["render",u]]);export{C as __pageData,w as default};
